<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\SpecialCategoryService;
Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_POST['round_id']??0);$return=(string)($_POST['return_to']??'index.php');
if(!in_array($return,['index.php','automatic-round.php'],true))$return='index.php';
try{if($_SERVER['REQUEST_METHOD']!=='POST'||!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$s=$pdo->prepare('SELECT division,yes_count FROM bdc_scoring_rounds WHERE id=:id');$s->execute(['id'=>$roundId]);$round=$s->fetch();if(!$round||!SpecialCategoryService::isSpecial((string)$round['division']))throw new RuntimeException('Special-category round not found.');$m=$pdo->prepare("SELECT COUNT(*) FROM bdc_scoring_marks WHERE round_id=:id AND (mark_type<>'blank' OR weighted_score>0)");$m->execute(['id'=>$roundId]);if((int)$m->fetchColumn()>0)throw new RuntimeException('The YES tier cannot be changed or unlocked after judging has started.');$action=(string)($_POST['action']??'');if($action==='special_settings_lock'){$yes=(int)($_POST['special_yes_count']??0);if(!in_array($yes,[5,10,15],true))throw new RuntimeException('Select 5, 10 or 15 YES per judge.');$pdo->prepare('UPDATE bdc_scoring_rounds SET yes_count=:yes,callback_count=:yes,tier_manual_override=1,yes_weight=10.00,alt1_weight=4.50,alt2_weight=4.30,alt3_weight=4.20 WHERE id=:id')->execute(['yes'=>$yes,'id'=>$roundId]);}elseif($action==='special_settings_unlock'){$pdo->prepare('UPDATE bdc_scoring_rounds SET tier_manual_override=0 WHERE id=:id')->execute(['id'=>$roundId]);}else throw new RuntimeException('Invalid special-category settings action.');}catch(Throwable $e){$_SESSION['scoring_error']=$e->getMessage();}
header('Location: '.$return.'?mode=automated&round_id='.$roundId,true,303);exit;
